Secure Checkout & Payment Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(secure_checkout_payment_service, "Secure Checkout & Payment Service") {
    Component(Checkout_Controller, "Checkout Controller", "AWS ECS/EKS container REST/gRPC API", "Handles incoming checkout requests and route operations via mTLS and JWTs.")
    Component(Payment_Processor, "Payment Processor", "AWS ECS/EKS container HTTPS/TLS 1.3", "Processes secure tokenized payments with the External Payment Gateway.")
    Component(Order_Fulfillment_Manager, "Order & Fulfillment Manager", "AWS ECS/EKS container", "Coordinates order fulfillment with Third-Party Shipping Provider APIs via HMAC-verified webhooks.")
    Component(Messaging_Resiliency_Handler, "Messaging & Resiliency Handler", "AWS SQS Dead Letter Queues", "Manages asynchronous messaging, webhook/payment failures, and circuit-breaker handling.")
}

Rel(Checkout_Controller, Payment_Processor, "Delegates tokenized payment requests", "")
Rel(Payment_Processor, Messaging_Resiliency_Handler, "Sends failed payment transactions to Dead Letter Queues", "")
Rel(Order_Fulfillment_Manager, Messaging_Resiliency_Handler, "Handles asynchronous webhook failures and retry queues", "")
@enduml

Recommendation Engine.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(recommendation_engine, "Recommendation Engine") {
    Component(Inference Service, "Inference Service", "AWS ECS/EKS Container", "Handles real-time gRPC inference for personalized book recommendations.")
    Component(Model Ingestion Module, "Model Ingestion Module", "AWS S3 and sigstore/Notation", "Ingests and verifies cryptographically signed model weights across multi-region buckets.")
    Component(Fallback and Cache Handler, "Fallback and Cache Handler", "Redis and Edge CDN", "Serves cached public trending fallback payloads to anonymous or unauthenticated users and provides circuit breaking.")
    Component(Compliance and Security Module, "Compliance and Security Module", "mTLS, JWT, AWS X-Ray, Automated TTL", "Enforces security, token validation, distributed tracing, and automated GDPR/CCPA data purges.")
}

Rel(Inference Service, Model Ingestion Module, "Fetches verified model weights")
Rel(Inference Service, Fallback and Cache Handler, "Falls back to cached payloads for unauthenticated users")
@enduml
